import type { Range } from '@tanstack/react-virtual';
import { ColumnInstance, type HeaderGroup } from 'react-table';

import {
  DATA_TABLE_DEFAULT_COLUMN_WIDTH,
  DATA_TABLE_DEFAULT_MIN_COLUMN_WIDTH,
} from '../DataTable/constants.js';

export const calculateVirtualHeight = (
  height: number | undefined,
  isContainedVariant: boolean | undefined,
): number | undefined => {
  // If no height is given, all elements will be shown.
  // Height will not be limited.
  if (height === undefined) {
    return undefined;
  }
  // take the contained border width of 2px * 2 into consideration
  const innerHeight = height - (isContainedVariant ? 4 : 0);
  return innerHeight >= 0 ? innerHeight : undefined;
};

/**
 * This function estimates the column width, considering the width, minWidth, maxWidth that have been set.
 * By default a column is estimated at 100px.
 * @param column - the column to be estimated
 * @returns estimated width
 */
export const getEstimatedWidth = (column?: ColumnInstance) => {
  let estimatedWidth = DATA_TABLE_DEFAULT_COLUMN_WIDTH;
  if (column) {
    if (column.width || column.minWidth || column.maxWidth) {
      estimatedWidth = Math.min(
        Math.max(
          column.minWidth || DATA_TABLE_DEFAULT_MIN_COLUMN_WIDTH,
          column.width || DATA_TABLE_DEFAULT_COLUMN_WIDTH,
        ),
        column.maxWidth || Number.MAX_SAFE_INTEGER,
      );
    }
  }
  return estimatedWidth;
};

/**
 * Function used to dynamically measure the height of a virtualized element.
 * To avoid jumping when a column with different height gets virtualized, the first measured row height
 * will remain and not change in case column virtualization is enabled.
 *
 * @param element - the element to measure
 * @param entry - resize observer entry
 * @param columnVirtualization - flag whether column virtualization is enabled
 * @returns the measured row element height
 */
export const measureRowHeight = (
  element: HTMLElement,
  entry: ResizeObserverEntry,
  columnVirtualization: boolean,
) => {
  const height = entry?.contentRect.height;
  const existingStyle = element.getAttribute('style');
  const isExpandableRow = element.classList.contains(
    'strato-table-row-expandable',
  );

  if (
    columnVirtualization &&
    height &&
    !isExpandableRow &&
    !existingStyle?.includes('height')
  ) {
    element.setAttribute(
      'style',
      existingStyle + ` height: ${height}px; overflow: hidden;`,
    );
  }

  // original implementation from react-virtual
  if (entry?.borderBoxSize) {
    const box = entry.borderBoxSize[0];
    if (box) {
      return Math.round(box.blockSize);
    }
  }

  return Math.round(element.getBoundingClientRect().height);
};

/**
 * This function creates the array of virtual column indices that actually need to be rendered, including all child columns of a rendered parent, in case of flex layout.
 *
 * @param range - visible range indices from the virtualizer (including overscan)
 * @param childHeaders - all child headers
 * @param isFlexLayout - whether flex layout is currently applied
 * @returns indices of the virtual items that need to be rendered
 */
export const getVirtualItemsRange = (
  range: Range,
  isFlexLayout: boolean,
  childHeader?: HeaderGroup,
) => {
  const virtualItemsRange: number[] = [];
  let startIndex = Math.max(range.startIndex - range.overscan, 0);
  const endIndex = Math.min(range.endIndex + range.overscan, range.count - 1);

  // for flex layout, we always need to render all children of a parent group, to ensure the correct horizontal translation
  if (isFlexLayout && childHeader) {
    const firstChildColumn = childHeader?.headers[startIndex];
    const childIndex = firstChildColumn.parent?.columns?.findIndex(
      (childColumns) => childColumns.id === firstChildColumn.id,
    );

    if (childIndex && childIndex > 0) {
      startIndex = startIndex - childIndex;
    }
  }

  for (let i = startIndex; i <= endIndex; i++) {
    virtualItemsRange.push(i);
  }
  return virtualItemsRange;
};
